import{_ as e,o as r,c as a,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Orchestrator Meeting 2022-01-04","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2022-01-04","date":"2022-01-04T00:00:00.000Z","updated":"2022-01-12T00:00:00.000Z","tags":["Ceph","CPU限制","NFS服务","OSD内存","Ceph Orchestrator"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Ceph_Orchestrator_Meeting_2022-01-04.md","filePath":"posts/2022/Ceph_Orchestrator_Meeting_2022-01-04.md","lastUpdated":1780460162000}'),o={name:"posts/2022/Ceph_Orchestrator_Meeting_2022-01-04.md"};function i(s,t,n,h,p,g){return r(),a("div",null,[...t[0]||(t[0]=[l('<p>Ceph Orchestrator Meeting 2022-01-04 会议纪要如下：</p><h4 id="会议概览" tabindex="-1">会议概览 <a class="header-anchor" href="#会议概览" aria-label="Permalink to &quot;会议概览&quot;">​</a></h4><ul><li><strong>日期</strong>: 2022年1月</li><li><strong>参与者</strong>: Ceph开发人员和相关领域的专家</li><li><strong>目的</strong>: 讨论Ceph服务的CPU限制实现、NFS服务测试和OSD内存目标设置等议题。</li></ul><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>CPU限制的实现</strong></p><ul><li><strong>讨论焦点</strong>: 是否采用全局CPU限制或针对每个服务设置，以及如何实现这一功能。</li><li><strong>决策</strong>: 决定针对每个服务设置CPU限制，并在服务规范中引入CPU和内存限制属性。</li></ul></li><li><p><strong>NFS服务测试</strong></p><ul><li><strong>讨论</strong>: 如何确保NFS服务在节点离线时能够正确切换。</li><li><strong>决策</strong>: 确认通过模拟连接失败来测试NFS服务的故障转移能力。</li></ul></li><li><p><strong>OSD内存目标设置</strong></p><ul><li><strong>讨论</strong>: 默认的OSD内存自动调整设置可能不适用于超融合基础设施（HCI）环境。</li><li><strong>决策</strong>: 决定默认启用OSD内存自动调整，并在文档中明确指出HCI环境可能需要调整设置。</li></ul></li></ol><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>开发团队将根据会议决定，在服务规范中引入CPU和内存限制属性，并进行相应的实现和测试。</li><li>开发团队将实施模拟连接失败的测试方法，确保NFS服务的故障转移功能正常工作。</li><li>更新文档，明确指出HCI环境可能需要调整OSD内存自动调整设置，并提供参考文档和示例。</li></ul><h4 id="其他事项" tabindex="-1">其他事项 <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项&quot;">​</a></h4><ul><li>会议还讨论了其他技术细节和实现问题，但主要决策和行动计划如上所述。</li></ul><p>会议在积极氛围中结束，参与者对即将到来的2022年充满期待，并承诺将继续努力推动Ceph项目的发展。</p>',10)])])}const d=e(o,[["render",i]]);export{c as __pageData,d as default};
